class HighLoadClient(DesktopClient):
    def __init__(
        self,
        uin: str,
        phone: Optional[str] = None,
        code: Optional[str] = None,
        api_url: str = "https://u.icq.net",
        binary_api_url: str = "https://ub.icq.net",
        api_ver: int = 92,
        env: env_types = "SANDBOX",
        email_password: Optional[str] = None,
        email_url: Optional[str] = None,
        forced_ip: Optional[str] = None,
        session: FastHttpUser = None,
        fix_otp: Optional[str] = None,
        org_struct_admin_token: Optional[str] = None,
        assert_caps: Optional[list[str]] = None,
        interest_caps: Optional[list[str]] = [  # noqa
            "8eec67ce70d041009409a7c1602a5c84",
            "094613504c7f11d18222444553540000," "094613514c7f11d18222444553540000",
            "094613503c7f11d18222444553540000",
        ],
        polling: bool = False,
        check_response: bool = True,
        token: Optional[str] = None,
        aimsid: Optional[str] = None,
        fetch_url: Optional[str] = None,
        *args,  # noqa
        **kwargs,  # noqa
    ):
        super().__init__(
            uin=uin,
            phone=phone,
            code=code,
            api_url=api_url,
            binary_api_url=binary_api_url,
            api_ver=api_ver,
            env=env,
            email_password=email_password,
            email_url=email_url,
            forced_ip=forced_ip,
            session=session,
            fix_otp=fix_otp,
            org_struct_admin_token=org_struct_admin_token,
            assert_caps=assert_caps,
            interest_caps=interest_caps,
            polling=polling,
            check_response=check_response,
            token=token,
            aimsid=aimsid,
            fetch_url=fetch_url,
            *args,  # noqa
            **kwargs,
        )

    def allure_attach(
        self,
        response: FastResponse,
        return_str: bool = False,
        *args,
        **kwargs,
    ) -> str:
        """
        Функция для логирования запроса-ответа в Allure отчете

        """
        response.encoding = "UTF-8"

        date_str = str(datetime.now())
        headers_str = "\n".join([f"{k}: {v}" for k, v in response.request.headers.items()])

        text = f"{date_str}\n" f"{response.request.method} {response.request.url}\n" f"{headers_str}\n"

        if response.request.body:
            if isinstance(response.request.body, str):
                text += "\n" f"{unquote(response.request.body)}"

            elif isinstance(response.request.body, (bytes, bytearray)) and len(response.request.body) < 1000:
                try:
                    text += "\n" f"{unquote(response.request.body)}"
                except UnicodeDecodeError:
                    text += "\n" f"Bytes {len(response.request.body)}"

            else:
                text += "\n" f"{type(response.request.body)}"

        text = text.strip()

        headers_str = "\n".join([f"{k}: {v}" for k, v in response.headers.items()])

        text += f"\n\n{response.status_code}\n" f"IP: {self.forced_ip}\n" f"{headers_str}\n"

        if response.text:
            if isinstance(response.text, str):
                text += "\n" f"{response.text}"
            else:
                text += "\n" f"{response.content.decode()}"

        return text

    def check_response(self, response: FastResponse, name: str) -> dict | str | bytes:
        """
        Проверка кода ответа API
        """
        try:
            response_json = response.json()
        except Exception as error:
            self.logger.error(error)
            response_json = {"not_json": True}

        response_status_code = int(
            (response_json.get("status") if isinstance(response_json.get("status"), int) else None)
            or response_json.get("status", {}).get("code")
            or response_json.get("response", {}).get("statusCode")
            or response_json.get("status")
            or response.status_code,
        )

        try:
            response_status_state = str(response_json.get("response", {}).get("data", {}).get("state")) or "NoStateText"
        except Exception as error:
            self.logger.warning(error)
            response_status_state = "NoStateText"

        try:
            if isinstance(response_json.get("results"), dict):
                results_text = ":".join(
                    ["{id}-{error}".format(**x) for x in response_json.get("results", {}).get("failures", [])],
                )
            else:
                results_text = None

            response_status_text = str(
                response_json.get("description")
                or response_json.get("response", {}).get("statusText")
                or (
                    response_json.get("status", {}).get("reason")
                    if isinstance(response_json.get("status"), dict)
                    else None
                )
                or results_text
                or "NoStatusText",
            )
        except Exception as error:
            self.logger.warning(error)
            response_status_text = "NoStatusText"

        if response_status_state == "failed":
            raise SendImStateException(
                env=self.env,
                path_url=name,
                response_status_code=response_status_code,
                response_status_text=f'state: "{response_status_state}", status_text: {response_status_text}',
            )

        elif response_status_code == 221:
            raise ScheduledMessageAsRegularOne(
                env=self.env,
                path_url=name,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
            )

        elif response_status_code == 400 and "statusDetailCode 7" in response_status_text:
            raise RequestException(
                env=self.env,
                path_url=name,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
            )

        elif response_status_code == 502:
            raise BadGatewayException(
                env=self.env,
                path_url=name,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
            )

        elif response_status_code == 423:
            raise WAFRequestBlocked(
                env=self.env,
                path_url=name,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
            )

        elif response_status_code == 40300 and "/files/" in response.request.url:
            raise RequestException(
                env=self.env,
                path_url=name,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
            )

        elif response_status_code in [20070] and "rapi/group/members/add" in response.request.url:
            raise UserMustJoinByLinkException(
                env=self.env,
                path_url=name,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
            )

        elif response_status_code == 301:
            raise TooManyRedirectsException(
                env=self.env,
                path_url=name,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
            )

        elif response_status_code == 330:
            raise RequestException(
                env=self.env,
                path_url=name,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
            )

        elif response_status_code in [400, 40000]:
            raise BadRequestException(
                env=self.env,
                path_url=name,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
            )

        elif response_status_code in [40008, 40403, 40405, 40401] and "rapi/orgstructure" in response.request.url:
            raise OrgstructureException(
                env=self.env,
                path_url=name,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
            )

        elif response_status_code == 40401:
            return response_json

        elif response_status_code in [403, 40003, 40300, 40200]:
            if "auth check failed" in response_status_text or response_status_text == "Invalid token":
                raise RequestException(
                    env=self.env,
                    path_url=name,
                    response_status_code=response_status_code,
                    response_status_text=response_status_text,
                )
            else:
                raise AccessDeniedException(
                    env=self.env,
                    path_url=name,
                    response_status_code=response_status_code,
                    response_status_text=response_status_text,
                )

        elif response_status_code in [404, 40400, 40004]:
            raise HttpNotFoundException(
                env=self.env,
                path_url=name,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
            )

        elif response_status_code in [429, 430]:
            raise RatelimitException(
                env=self.env,
                path_url=name,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
            )

        elif response_status_code in (460, 462, 40000):
            raise MissingParameterException(
                env=self.env,
                path_url=name,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
            )

        elif 400 <= response_status_code < 500 or 40000 <= response_status_code < 50000:
            raise RequestException(
                env=self.env,
                path_url=name,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
            )

        elif 200 <= response_status_code < 400 or 20000 <= response_status_code < 40000:
            if not response_json.get("not_json", False):
                return response_json
            else:
                return response.text

        else:
            raise ServerException(
                env=self.env,
                path_url=name,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
            )

    def request(
        self,
        method: Literal["GET", "POST"],
        url: str,
        headers: Optional[dict[str, str]] = None,
        params: Optional[dict] = None,
        json: Optional[dict] = None,
        data: Optional[dict] = None,
        files=None,
        ignore_check: bool = False,
        stream: bool = False,
        allow_redirects: bool = True,
        timeout: tuple[int | float, int | float] | int | float = (5.0, 40.0),
        name: Optional[str] = None,
    ) -> dict | str | bytes:
        self.session: FastHttpUser

        with self.session.rest(
            method=method,
            url=url,
            headers=headers,
            params=params,
            json=json,
            data=data,
            files=files,
            stream=True,
            allow_redirects=allow_redirects,
            timeout=timeout,
            name=name,
        ) as response:
            response.encoding = "UTF-8"
            try:
                response_result = self.check_response(response=response, name=name)
                response.success()
            except Exception as error:
                response.failure(error)
                try:
                    response_result = response.json()
                except Exception as encode_exc:
                    self.logger.warning(encode_exc)
                    response_result = response.text

            return response_result

    def get(
        self,
        path: str,
        allow_redirects: bool = True,
        headers: Optional[dict] = None,
        name: Optional[str] = None,
        **kwargs,
    ) -> Union[dict, str]:
        """
        Оболочка для GET запросов к api ICQ/Myteam
        :param path: path для запроса
        :param headers:
        :param allow_redirects:
        :return: результат выполнения запроса (код и тело ответа)
        """
        return self.request(
            method="GET",
            url="/".join([self.base_url, path]),
            params=kwargs,
            allow_redirects=allow_redirects,
            headers=headers,
            name=name if name is not None else f"/api/[api version]/{path}",
        )

    def post(
        self,
        path: str,
        params: Optional[dict] = None,
        headers: Optional[dict] = None,
        json: Optional[dict] = None,
        data: Optional[dict] = None,
        files=None,
        allow_redirects: bool = True,
        name: Optional[str] = None,
    ) -> Union[dict, str]:
        """
        Оболочка для POST запросов к api ICQ/Myteam
        :return: результат выполнения запроса (код и тело ответа)
        """
        return self.request(
            method="POST",
            url="/".join([self.base_url, path]),
            params=params,
            headers=headers,
            json=json,
            data=data,
            files=files,
            allow_redirects=allow_redirects,
            name=name if name is not None else f"/api/[api version]/{path}",
        )

    def files_info(
        self,
        file_id: str,
        preview: list[str] = (),
        previews: list[str] = (),
        source: Optional[str] = None,
        ptt_text: int = 0,
        support_webp: int = 0,
    ) -> dict:
        """
        Данный метод возвращает информацию о файле.
        Такую, как ссылки на превью, мета-информация и т.д.
        :param file_id: уникальный file_id хэш файла,
        например 28g8gk2L0MDQ2vndaxW9r45a326ee91ab
        :param preview: Превью, которые необходимы в ответе
        :param previews: Список (через запятую) названий превью,
        которые необходимы в ответе
        :param source:
        :param ptt_text: Добавить в ответ текст
        распознанного голосового сообщения
        :param support_webp: Если параметр выставлен в 1,
        то клиент поддерживает webp.
        Если клиент поддерживает webp и запросил info по неанимированному
        стикеру или webp-изображению,
        то в ответ получит mime: image/webp и размер оригинала в формате webp;
        Если клиент не поддерживает webp,
        но запрашивает info о webp-изображении,
        то в ответ он получит mime: image/png и размер оригинала в формате png;
        Для всех остальных случаев info возвращает mime
        и размер файла без преобразований.
        :return: тело ответа сервера
        """
        return self.get(
            f"files/info/{file_id}",
            aimsid=self.aimsid,
            preview=preview,
            previews=",".join(previews),
            source=source,
            ptt_text=ptt_text,
            support_webp=support_webp,
            name="/api/[api version]/files/info/[file_id]",
        )

    def upload_file(
        self,
        file_path: Union[str, pathlib.Path],
        _type: Optional[str] = None,
        chunk_size: int = 64 * 10000,
    ) -> tuple[str, str]:
        """
        Загружает файл в мессенджер.
        Содержит ассерты для проверки успешности операции.

        :return: file_id, result
        """
        if isinstance(file_path, str):
            file_path = pathlib.Path(file_path)

        file_name = file_path.name
        file_size = file_path.stat().st_size

        if chunk_size <= 0:
            chunk_size = file_size

        result = self.files_init(filename=file_name, size=file_size, type=_type, duration=5)
        status_code = result["status"]["code"]

        assert status_code == 200, "Не удалось инициировать загрузку файла (files/init): " "код ответа: {}".format(
            status_code,
        )

        chunks_count = file_size / chunk_size

        full_chunks_count = int(chunks_count)

        chunks_count = int(chunks_count) + (1 if chunks_count % 1 else 0) - 1

        last_chunk_size = file_size - chunk_size * full_chunks_count

        for i, chunk in enumerate(read_in_chunks(file_path.absolute(), blocksize=chunk_size)):
            if i < chunks_count:
                content_range = f"bytes {i * chunk_size}-{(i + 1) * chunk_size - 1}/{file_size}"
            else:
                content_range = (
                    f"bytes "
                    f"{full_chunks_count * chunk_size}"
                    f"-"
                    f"{full_chunks_count * chunk_size + last_chunk_size - 1}"
                    f"/"
                    f"{file_size}"
                )
            self.request(
                method="POST",
                url="https://{host}{url}".format(**result["result"]),
                headers={"Content-Range": content_range},
                params={
                    "aimsid": self.aimsid,
                    "f": "json",
                    "k": self.devId,
                    "size": file_size,
                    "client": "myteam",
                },
                data=chunk,
                name="/api/[api version]/files/server/onpremise/upload/[bucket]/",
            )
        else:
            f_result: dict[str, Any] = self.request(
                method="POST",
                url="https://{host}{complete_url}".format(**result["result"]),
                params={
                    "aimsid": self.aimsid,
                    "f": "json",
                    "k": self.devId,
                    "size": file_size,
                    "client": "myteam",
                },
                headers={"Content-Range": content_range},  # noqa
                data=chunk,  # noqa
                name="/api/[api version]/files/server/onpremise/upload/[bucket]/",
            )

        return f_result["result"]["fileid"], f_result["result"]["static_url"]

    def bos_fetchEvents(self, rewrite: bool = True, timeout: int = 600):
        """
        Первичный урл для fetch запроса выдается в ответе на startSession.
        :return: тело ответа сервера
        """
        if self.fetch_url is None:
            raise ValueError("/bos/fetchEvents url is None")

        if "eventsStream" in self.fetch_url:
            return self.get_event_stream(timeout=timeout)

        else:
            parsed_url = urlparse(self.fetch_url)

            query: dict[str, str | int | list[str | int]] = parse_qs(parsed_url.query)

            for key, value in query.copy().items():
                if len(value) == 1:
                    query[key] = value[0]

            if rewrite:
                query["timeout"] = timeout

            result = self.request(
                method="GET",
                url="{url.scheme}://{url.netloc}{url.path}".format(url=parsed_url),
                params=query,
                name="/api/[api version]/bos/[bos id]/aim/fetchEvents",
            )
            if "fetchBaseURL" in result["response"]["data"]:
                self.fetch_url = result["response"]["data"]["fetchBaseURL"]

                parsed_url = urlparse(self.fetch_url)
                query = parse_qs(parsed_url.query)

                assert self.aimsid == query["aimsid"][-1], f"{self.env}:FetchEvents aimsid not equal to main aimsid"

            return result

    def get_event_stream(self, timeout: int = 600):
        response = self.request(
            method="GET",
            url=self.fetch_url,
            stream=True,
            timeout=timeout,
            name="/api/[api version]/bos/[bos id]/aim/fetchEvents",
        )

        try:
            events = []
            response_json = None

            for response_json in self.yield_streaming_response(response):
                self.logger.info(f"eventsStream chunk: {response_json}")
                self.fetch_url = response_json["response"]["data"]["fetchBaseURL"]
                events.extend(response_json["response"]["data"]["events"])

            response_json["response"]["data"]["events"] = events
            self.logger.info(response_json)

            return response_json
        except Exception as error:
            self.logger.exception(error)
            raise error
